import { useMutation } from '@tanstack/react-query';
import { z } from 'zod';

import { useNotifications } from '@/components/ui/notifications';
import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';

export const updatePasswordInputSchema = z
  .object({
    currentPassword: z.string().min(1, 'Required'),
    newPassword: z.string().min(6, 'Must be at least 6 characters'),
    confirmPassword: z.string().min(1, 'Required'),
  })
  .refine((values) => values.newPassword === values.confirmPassword, {
    message: 'Passwords do not match',
    path: ['confirmPassword'],
  });

export type UpdatePasswordInput = z.infer<typeof updatePasswordInputSchema>;

export const updatePassword = ({ data }: { data: UpdatePasswordInput }) => {
  return api.patch(`/users/password`, {
    currentPassword: data.currentPassword,
    newPassword: data.newPassword,
  });
};

type UseUpdatePasswordOptions = {
  mutationConfig?: MutationConfig<typeof updatePassword>;
};

export const useUpdatePassword = ({
  mutationConfig,
}: UseUpdatePasswordOptions = {}) => {
  const { addNotification } = useNotifications();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      addNotification({
        type: 'success',
        title: 'Password Updated',
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updatePassword,
  });
};
EOF
